using NAudio.Wave;
namespace SafetyMonitor;
internal sealed partial class MainForm
{
    void StartCapture(){if(capture!=null||deviceBox.SelectedIndex<0)return;try{capture=new WasapiCapture(devices[deviceBox.SelectedIndex]);format=capture.WaveFormat;int ch=format.Channels;if((int)leftCh.Value>=ch||(int)rightCh.Value>=ch||(int)micCh.Value>=ch)throw new InvalidOperationException($"Il dispositivo espone {ch} canali.");capture.DataAvailable+=OnData;capture.RecordingStopped+=(_,e)=>BeginInvoke(()=>{if(e.Exception!=null)AddLog("INPUT ERROR: "+e.Exception.Message);StopCapture();});peakL=peakR=rmsL=rmsR=holdL=holdR=-120;clipsL=clipsR=0;leqEnergy=leqSeconds=0;splNow=double.NaN;capture.StartRecording();startBtn.Enabled=false;stopBtn.Enabled=true;SetStatus("SAFE",Color.LimeGreen);AddLog($"START {devices[deviceBox.SelectedIndex].FriendlyName} | {format.SampleRate} Hz | {format.Channels} ch");}catch(Exception ex){MessageBox.Show(ex.Message,"Safety Monitor");capture?.Dispose();capture=null;}}
    void StopCapture(){if(capture==null)return;try{capture.StopRecording();}catch{}capture.Dispose();capture=null;startBtn.Enabled=true;stopBtn.Enabled=false;SetStatus("STOPPED",Color.Silver);AddLog("STOP");}
    void OnData(object? s,WaveInEventArgs e){var f=format!;int bps=f.BitsPerSample/8,frame=bps*f.Channels;if(frame<=0)return;int li=(int)leftCh.Value,ri=(int)rightCh.Value,mi=(int)micCh.Value;double sumL=0,sumR=0,sumMic=0;int n=0;double pL=0,pR=0;double lowE=0,midE=0,highE=0,prev=0;
        for(int o=0;o+frame<=e.BytesRecorded;o+=frame){double l=Sample(e.Buffer,o+li*bps,f),r=Sample(e.Buffer,o+ri*bps,f),m=mi>=0?Sample(e.Buffer,o+mi*bps,f):double.NaN;pL=Math.Max(pL,Math.Abs(l));pR=Math.Max(pR,Math.Abs(r));sumL+=l*l;sumR+=r*r;if(Math.Abs(l)>=.999999)clipsL++;if(Math.Abs(r)>=.999999)clipsR++;double mono=(l+r)*.5,d=mono-prev;prev=mono;lowE+=mono*mono;midE+=d*d;highE+=(d-mono*.1)*(d-mono*.1);if(mi>=0)sumMic+=m*m;n++;}
        if(n==0)return;double pkL=Db(pL),pkR=Db(pR),rrL=Db(Math.Sqrt(sumL/n)),rrR=Db(Math.Sqrt(sumR/n)),micR=mi>=0?Db(Math.Sqrt(sumMic/n)):double.NaN;lock(gate){peakL=pkL;peakR=pkR;rmsL=rrL;rmsR=rrR;if(pkL>holdL){holdL=pkL;holdTimeL=DateTime.UtcNow;}if(pkR>holdR){holdR=pkR;holdTimeR=DateTime.UtcNow;}low=Db(Math.Sqrt(lowE/n));mid=Db(Math.Sqrt(midE/n));high=Db(Math.Sqrt(highE/n));micDbfs=micR;if(mi>=0&&!double.IsNaN(splOffset)){splNow=micR+splOffset;double sec=n/(double)f.SampleRate;leqEnergy+=Math.Pow(10,splNow/10)*sec;leqSeconds+=sec;}}}
    static double Sample(byte[] b,int o,WaveFormat f){if(f.Encoding==WaveFormatEncoding.IeeeFloat&&f.BitsPerSample==32)return BitConverter.ToSingle(b,o);if(f.BitsPerSample==16)return BitConverter.ToInt16(b,o)/32768.0;if(f.BitsPerSample==24){int v=b[o]|(b[o+1]<<8)|(b[o+2]<<16);if((v&0x800000)!=0)v|=unchecked((int)0xFF000000);return v/8388608.0;}if(f.BitsPerSample==32)return BitConverter.ToInt32(b,o)/2147483648.0;return 0;}
    static double Db(double x)=>x>1e-12?20*Math.Log10(x):-120;
    void Calibrate(){if(capture==null){MessageBox.Show("Avvia prima l'acquisizione.");return;}if((int)micCh.Value<0){MessageBox.Show("Seleziona un canale MIC separato. Lo SPL non viene ricavato dal master dBFS.");return;}double m;lock(gate)m=micDbfs;if(double.IsNaN(m)||m<-100){MessageBox.Show("Segnale microfono insufficiente.");return;}splOffset=(double)calRef.Value-m;leqEnergy=leqSeconds=0;AddLog($"CALIBRATION ref={(double)calRef.Value:F1} dB SPL, mic={m:F2} dBFS, offset={splOffset:F2} dB");MessageBox.Show("Calibrazione applicata. Se cambi gain, dispositivo, canale o sample rate, ricalibra.");}
}
